        stack: [{ name: "NICE CXone", role: "CCaaS", why: "Product-line routing with SKU-level agent specialization. Handles the breadth of consumer electronics, from headphones to smart TVs to home security, with appropriate routing to trained specialists.", href: "/vendors/nice-cxone" }],
