        stack: [{ name: "FDA/FSIS compliance systems", role: "Regulatory", why: "Some consumer complaints can make a food reportable to FDA, with a short clock. Contact center agents must recognize possible reportable events and escalate immediately to regulatory affairs.", href: "/vendors" }],
