        stack: [{ name: "SAP / Oracle QMS", role: "Quality Management", why: "Complaint intake, investigation tracking, and CAPA (Corrective and Preventive Action) management. The system that connects a consumer complaint to a production investigation to a process improvement.", href: "/vendors" }],
